import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const o="/img/rowing-problems-logic.svg",d=JSON.parse('{"title":"小学奥数专项：流水行船问题一（顺流与逆流）","description":"","frontmatter":{"title":"小学奥数专项：流水行船问题一（顺流与逆流）","date":"2026-02-27T16:00:00.000Z","tags":["奥数","四年级","行程问题"],"categories":["教育","数学"]},"headers":[],"relativePath":"posts/primary-math-olympiad-rowing-problems.md","filePath":"posts/primary-math-olympiad-rowing-problems.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-rowing-problems.md"};function l(e,a,i,p,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="流水行船-当运动遇上流动的媒介" tabindex="-1">流水行船：当运动遇上流动的媒介 <a class="header-anchor" href="#流水行船-当运动遇上流动的媒介" aria-label="Permalink to &quot;流水行船：当运动遇上流动的媒介&quot;">​</a></h1><p>流水行船问题是行程问题中的一种特殊情况。与普通的陆地行程不同，船在水中行驶时，水流会给予船一个额外的推力或阻力。</p><h2 id="_1-四个核心速度及其关系" tabindex="-1">1. 四个核心速度及其关系 <a class="header-anchor" href="#_1-四个核心速度及其关系" aria-label="Permalink to &quot;1. 四个核心速度及其关系&quot;">​</a></h2><p>在流水行船问题中，我们要区分四个速度：</p><ol><li><strong>船速 (V船)</strong>：船在静水中的行驶速度（也叫静水速度）。</li><li><strong>水速 (V水)</strong>：水流动的速度。</li><li><strong>顺流速度 (V顺)</strong>：船顺着水流方向行驶的速度。</li><li><strong>逆流速度 (V逆)</strong>：船逆着水流方向行驶的速度。</li></ol><p><img src="'+o+'" alt="流水行船逻辑图"></p><h3 id="核心计算公式" tabindex="-1">核心计算公式： <a class="header-anchor" href="#核心计算公式" aria-label="Permalink to &quot;核心计算公式：&quot;">​</a></h3><ul><li><strong>顺流速度 = 船速 + 水速</strong></li><li><strong>逆流速度 = 船速 - 水速</strong></li></ul><h3 id="两个重要的推导公式-和差问题应用" tabindex="-1">两个重要的推导公式（和差问题应用）： <a class="header-anchor" href="#两个重要的推导公式-和差问题应用" aria-label="Permalink to &quot;两个重要的推导公式（和差问题应用）：&quot;">​</a></h3><ul><li><strong>船速 = (顺流速度 + 逆流速度) ÷ 2</strong></li><li><strong>水速 = (顺流速度 - 逆流速度) ÷ 2</strong></li></ul><hr><h2 id="_2-经典例题详解" tabindex="-1">2. 经典例题详解 <a class="header-anchor" href="#_2-经典例题详解" aria-label="Permalink to &quot;2. 经典例题详解&quot;">​</a></h2><h3 id="例题-1-求顺流与逆流速度" tabindex="-1">例题 1：求顺流与逆流速度 <a class="header-anchor" href="#例题-1-求顺流与逆流速度" aria-label="Permalink to &quot;例题 1：求顺流与逆流速度&quot;">​</a></h3><p><strong>题目：</strong> 一只小船在静水中的速度是每小时 20 千米，水流速度是每小时 4 千米。这只船在河中顺流而下行驶 3 小时，路程是多少？如果逆流而上，行驶 3 小时又是多少路程？</p><p><strong>【解题步骤】</strong></p><ol><li><strong>求顺流速度：</strong> V_{顺} = 20 + 4 = 24（千米/小时）。</li><li><strong>求顺流路程：</strong> S_{顺} = 24 \\times 3 = 72（千米）。</li><li><strong>求逆流速度：</strong> V_{逆} = 20 - 4 = 16（千米/小时）。</li><li><strong>求逆流路程：</strong> S_{逆} = 16 \\times 3 = 48（千米）。 <strong>答：</strong> 顺流路程是 72 千米，逆流路程是 48 千米。</li></ol><hr><h3 id="例题-2-已知顺逆速度求基本速度" tabindex="-1">例题 2：已知顺逆速度求基本速度 <a class="header-anchor" href="#例题-2-已知顺逆速度求基本速度" aria-label="Permalink to &quot;例题 2：已知顺逆速度求基本速度&quot;">​</a></h3><p><strong>题目：</strong> 一只轮船顺流而下行驶 80 千米需 4 小时，逆流而上行驶这段路程需 5 小时。求这只轮船在静水中的速度和水流速度。</p><p><strong>【分析】</strong></p><ul><li>先算出顺流和逆流的<strong>实际速度</strong>。</li><li>再利用推导公式算出船速和水速。</li></ul><p><strong>【解题步骤】</strong></p><ol><li>顺流速度：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mn>0</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">80 \\div 4 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>（千米/小时）。</li><li>逆流速度：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">80 \\div 5 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span>（千米/小时）。</li><li>船速：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>6</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">(20 + 16) \\div 2 = 18</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">8</span></span></span></span>（千米/小时）。</li><li>水速：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>0</mn><mo>−</mo><mn>1</mn><mn>6</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">(20 - 16) \\div 2 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>（千米/小时）。 <strong>答：</strong> 船在静水中的速度是 18 千米/小时，水流速度是 2 千米/小时。</li></ol><hr><h2 id="_3-引导性思考-流水中的-相遇与追及" tabindex="-1">3. 引导性思考：流水中的“相遇与追及” <a class="header-anchor" href="#_3-引导性思考-流水中的-相遇与追及" aria-label="Permalink to &quot;3. 引导性思考：流水中的“相遇与追及”&quot;">​</a></h2><p>当两只船在同一条河流中运动时，水流速度会相互抵消吗？</p><ul><li><p><strong>相遇问题：</strong> 一船顺流，一船逆流。</p><ul><li><strong>速度和 = (V船1 + V水) + (V船2 - V水) = V船1 + V船2</strong></li><li><strong>结论：</strong> 两船在河中相遇的时间，与在静水中相遇的时间<strong>完全相同</strong>。水速不影响相遇时间！</li></ul></li><li><p><strong>追及问题：</strong> 两船同向行驶。</p><ul><li><strong>速度差 = (V船1 + V水) - (V船2 + V水) = V船1 - V船2</strong></li><li><strong>结论：</strong> 追及时间也与水速无关！</li></ul></li></ul><hr><h2 id="_4-引申思考-漂流物问题" tabindex="-1">4. 引申思考：漂流物问题 <a class="header-anchor" href="#_4-引申思考-漂流物问题" aria-label="Permalink to &quot;4. 引申思考：漂流物问题&quot;">​</a></h2><p>如果一个救生圈掉进河里，它会以什么速度移动？</p><ul><li><strong>漂流速度 = 水速</strong></li><li>常见的题目：“甲船顺流而下，半路掉下一个救生圈，10 分钟后才发现……”这类题目其实就是<strong>水速</strong>与<strong>船速</strong>的追及问题。</li></ul><hr><h2 id="_5-闯关练习" tabindex="-1">5. 闯关练习 <a class="header-anchor" href="#_5-闯关练习" aria-label="Permalink to &quot;5. 闯关练习&quot;">​</a></h2><ol><li><strong>基础关：</strong> 船在静水中每小时行 15 千米，水速每小时 3 千米。顺流而下行 90 千米需要几小时？</li><li><strong>进阶关：</strong> 甲、乙两码头相距 120 千米。一艘货船顺流航行需 4 小时，逆流航行需 6 小时。求这艘货船在静水中的速度。</li><li><strong>挑战关：</strong> 一只船从甲地开往乙地，去时顺流每小时行 24 千米，返回时逆流。已知船在静水中的速度是每小时 20 千米，求往返一次的平均速度。 <em>(提示：先求出水速，再求出返回的速度和时间，最后用总路程除以总时间。)</em></li></ol><hr><p><strong>数学笔记：</strong> 处理流水行船，画好速度分量图。记住：顺流是“助力”，逆流是“阻力”！</p>',36)])])}const u=s(r,[["render",l]]);export{d as __pageData,u as default};
